class Solution {
    private boolean isPalindrome(String s, int l, int r) {
        while (l < r) {
            if (s.charAt(l++) != s.charAt(r--)) return false;
        }
        return true;
    }

    public List<List<Integer>> palindromePairs(String[] words) {
        Map<String, Integer> lookup = new HashMap<>();
        for (int i = 0; i < words.length; i++) {
            lookup.put(words[i], i);
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            int m = w.length();
            for (int j = 0; j <= m; j++) {
                if (isPalindrome(w, 0, j - 1)) {
                    String back = new StringBuilder(w.substring(j)).reverse().toString();
                    Integer idx = lookup.get(back);
                    if (idx != null && idx != i) {
                        res.add(Arrays.asList(idx, i));
                    }
                }
                if (j < m && isPalindrome(w, j, m - 1)) {
                    String back = new StringBuilder(w.substring(0, j)).reverse().toString();
                    Integer idx = lookup.get(back);
                    if (idx != null && idx != i) {
                        res.add(Arrays.asList(i, idx));
                    }
                }
            }
        }
        return res;
    }
}

var palindromePairs = function(words) {
