    for (let i = 0; i < words.length; i++) {
        lookup.set(words[i], i);
    }

    const res = [];
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        const m = w.length;
        for (let j = 0; j <= m; j++) {
